-- NFL players: mean flaw severity total and tool severity total by unit and season (craft items; sev/255)
rsql with it as (select lp.season s, case when lp.person__player__position in ('OT','IOL') then 'OL' when lp.person__player__position in ('DT','EDGE') then 'DL' when lp.person__player__position in ('CB','S') then 'DB' else lp.person__player__position end u, lp._row r, sum(case when json_extract(i.value,'$.code') in (1,2,3,4,5,9,10,11,14,15,16,17,21,22,23,24,25,27,28,29,30,34,35,36,37,40,41,42,43,46,47,48,50,51,54,55,56) then json_extract(i.value,'$.sev') else 0 end)/255.0 fl, sum(case when json_extract(i.value,'$.code') in (6,7,8,12,13,18,19,20,26,31,32,33,38,39,44,45,49,52,53) then json_extract(i.value,'$.sev') else 0 end)/255.0 tl from log_players lp, json_each(more('log_players', lp._more), '$.person.player.craft.items') i where lp.level = 'NFL' and lp.person__player__position in ('OT','IOL','DT','EDGE','LB','CB','S','RB','QB','WR','TE') group by lp._row) select u, s, count(*) n, round(avg(fl),3) flaws, round(avg(tl),3) tools, round(avg(tl-fl),3) net from it group by u, s order by u, s
